/** Governed cash collection, reconciliation, settlement, correction, and FX control. @author Tinashe K */
@Service
public class GovernedFinanceCollectionsService {
    private final ExchangeRateRepository exchangeRateRepository;private final StudentAccountPaymentRepository paymentRepository;
    private final StudentPaymentSuspenseResolutionRepository suspenseRepository;private final StudentPaymentReceiptRepository receiptRepository;
    private final StudentPaymentAllocationRepository allocationRepository;private final StudentPaymentAllocationReversalRepository allocationReversalRepository;
    private final StudentPaymentReversalRepository paymentReversalRepository;private final FinanceCreditNoteRepository creditNoteRepository;
    private final FinanceCreditNoteLineRepository creditNoteLineRepository;private final StudentFinanceAccountRepository accountRepository;
    private final FinanceInvoiceRepository invoiceRepository;private final FinanceInvoiceLineRepository invoiceLineRepository;
    private final FinanceReferenceGenerator referenceGenerator;private final Clock clock;

    public GovernedFinanceCollectionsService(ExchangeRateRepository exchangeRateRepository,StudentAccountPaymentRepository paymentRepository,
            StudentPaymentSuspenseResolutionRepository suspenseRepository,StudentPaymentReceiptRepository receiptRepository,
            StudentPaymentAllocationRepository allocationRepository,StudentPaymentAllocationReversalRepository allocationReversalRepository,
            StudentPaymentReversalRepository paymentReversalRepository,FinanceCreditNoteRepository creditNoteRepository,
            FinanceCreditNoteLineRepository creditNoteLineRepository,StudentFinanceAccountRepository accountRepository,
            FinanceInvoiceRepository invoiceRepository,FinanceInvoiceLineRepository invoiceLineRepository,
            FinanceReferenceGenerator referenceGenerator,Clock clock){this.exchangeRateRepository=exchangeRateRepository;this.paymentRepository=paymentRepository;this.suspenseRepository=suspenseRepository;this.receiptRepository=receiptRepository;this.allocationRepository=allocationRepository;this.allocationReversalRepository=allocationReversalRepository;this.paymentReversalRepository=paymentReversalRepository;this.creditNoteRepository=creditNoteRepository;this.creditNoteLineRepository=creditNoteLineRepository;this.accountRepository=accountRepository;this.invoiceRepository=invoiceRepository;this.invoiceLineRepository=invoiceLineRepository;this.referenceGenerator=referenceGenerator;this.clock=clock;}

    @Transactional(readOnly=true)
    public CollectionsRegister register(){return new CollectionsRegister(exchangeRateRepository.findAllByDeletedAtIsNullOrderByEffectiveFromDescSourceCurrencyCodeAsc().stream().map(this::rateView).toList(),paymentRepository.findAllByDeletedAtIsNullOrderByPaidAtDescPaymentNumberDesc().stream().map(this::paymentView).toList(),receiptRepository.findAllByDeletedAtIsNullOrderByIssuedAtDescReceiptNumberDesc().stream().map(this::receiptView).toList(),allocationRepository.findAllByDeletedAtIsNullOrderByAllocatedAtDescAllocationNumberDesc().stream().map(this::allocationView).toList(),creditNoteRepository.findAllByDeletedAtIsNullOrderByPreparedAtDescCreditNoteNumberDesc().stream().map(this::creditNoteView).toList());}
    @Transactional(readOnly=true) public List<StudentAccountSummary> accounts(){return accountRepository.findAllByDeletedAtIsNullOrderByStudentNumberAsc().stream().map(account->accountView(account,statementEntries(account).stream().map(StatementEntry::baseMovement).reduce(BigDecimal.ZERO,BigDecimal::add))).toList();}
    @Transactional(readOnly=true) public StudentAccountStatement statement(UUID accountId){StudentFinanceAccount account=accountRepository.findByIdAndDeletedAtIsNull(accountId).orElseThrow(()->new IllegalArgumentException("Student finance account was not found."));List<StatementEntry> entries=statementEntries(account).stream().sorted(Comparator.comparing(StatementEntry::occurredAt).thenComparing(StatementEntry::reference)).toList();BigDecimal running=BigDecimal.ZERO;List<StatementLine> lines=new ArrayList<>();for(StatementEntry entry:entries){running=running.add(entry.baseMovement());lines.add(new StatementLine(entry.lineType(),entry.reference(),entry.occurredAt(),entry.description(),entry.transactionCurrencyCode(),entry.transactionDebit(),entry.transactionCredit(),"USD",entry.baseDebit(),entry.baseCredit(),running));}return new StudentAccountStatement(accountView(account,running),lines);}

    @Transactional public ExchangeRateSummary createRate(CreateExchangeRate command,UUID actor){ExchangeRate rate=new ExchangeRate(command.sourceCurrencyCode(),command.rateToBase(),command.effectiveFrom(),command.effectiveTo(),command.sourceName(),command.sourceReference(),actor);return rateView(exchangeRateRepository.saveAndFlush(rate));}
    @Transactional public ExchangeRateSummary moveRate(UUID id,String action,ControlledDecision command,UUID actor){ExchangeRate rate=exchangeRateRepository.findLockedByIdAndDeletedAtIsNull(id).orElseThrow(()->new IllegalArgumentException("Exchange rate was not found."));if(rate.getVersion()!=command.expectedVersion())throw new IllegalStateException("Exchange rate changed since it was loaded. Refresh and try again.");if("approve".equals(action))rate.approve(actor,clock.instant(),command.reason());else if("retire".equals(action))rate.retire(actor,clock.instant(),command.reason());else throw new IllegalArgumentException("Unsupported exchange-rate action.");return rateView(exchangeRateRepository.saveAndFlush(rate));}

    @Transactional public PaymentSummary capture(CapturePayment command,UUID actor){String provider=required(command.providerCode(),"Provider code").toUpperCase(Locale.ROOT);String reference=required(command.providerTransactionReference(),"Provider transaction reference");String fingerprint=required(command.providerEventFingerprint(),"Provider event fingerprint");String currency=ExchangeRate.normalizeCurrencyCode(command.transactionCurrencyCode());StudentFinanceAccount account=command.studentFinanceAccountId()==null?null:requireActiveAccount(command.studentFinanceAccountId());StudentAccountPayment existing=paymentRepository.findByProviderCodeAndProviderTransactionReferenceAndDeletedAtIsNull(provider,reference).orElse(null);if(existing!=null){if(!existing.matches(account,fingerprint,command.transactionAmount(),currency,command.paidAt()))throw new IllegalStateException("Provider transaction reference was already captured with different immutable evidence.");return paymentView(existing);}paymentRepository.findByProviderEventFingerprintAndDeletedAtIsNull(fingerprint).ifPresent(duplicate->{throw new IllegalStateException("Provider event fingerprint was already captured as "+duplicate.getPaymentNumber()+".");});RatedAmount rated=rate(command.transactionAmount(),currency,command.paidAt());StudentAccountPayment payment=new StudentAccountPayment(referenceGenerator.nextStudentPaymentNumber(),account,command.payerName(),provider,reference,command.paymentChannel(),currency,command.transactionAmount(),rated.rate(),rated.baseAmount(),rated.status(),command.paidAt(),fingerprint,actor,clock.instant());try{return paymentView(paymentRepository.saveAndFlush(payment));}catch(DataIntegrityViolationException exception){throw new IllegalStateException("Payment provider evidence conflicts with an existing controlled record.",exception);}}
    @Transactional public PaymentSummary applyRate(UUID id,long expectedVersion,UUID actor){StudentAccountPayment payment=requirePayment(id);RatedAmount rated=rate(payment.getTransactionAmount(),payment.getTransactionCurrencyCode(),payment.getPaidAt());if(rated.status()!=StudentAccountPayment.RatingStatus.RATED||rated.rate()==null)throw new IllegalStateException("No single approved exchange rate is effective at the payment timestamp.");payment.applyRate(rated.rate(),rated.baseAmount(),actor,clock.instant(),expectedVersion);return paymentView(paymentRepository.saveAndFlush(payment));}
    @Transactional public PaymentSummary decidePayment(UUID id,String action,ControlledDecision command,UUID actor){StudentAccountPayment payment=requirePayment(id);Instant now=clock.instant();if("reconcile".equals(action)){payment.reconcile(actor,now,command.reason(),command.expectedVersion());paymentRepository.saveAndFlush(payment);if(payment.getStudentFinanceAccount()!=null)issueReceipt(payment,payment.getStudentFinanceAccount(),actor,now);}else if("reject".equals(action)){payment.reject(actor,now,command.reason(),command.expectedVersion());paymentRepository.saveAndFlush(payment);}else throw new IllegalArgumentException("Unsupported payment decision.");return paymentView(payment);}
    @Transactional public PaymentSummary resolveSuspense(UUID id,ResolveSuspense command,UUID actor){StudentAccountPayment payment=requirePayment(id);requireVersion(payment.getVersion(),command.expectedPaymentVersion(),"Payment");if(payment.getStudentFinanceAccount()!=null)throw new IllegalStateException("This payment was captured against a student account and is not in suspense.");if(payment.getReconciliationStatus()!=StudentAccountPayment.ReconciliationStatus.RECONCILED)throw new IllegalStateException("Only a reconciled payment can leave suspense.");if(payment.getCapturedByUserId().equals(actor))throw new IllegalStateException("Suspense resolution requires a different Finance operator from payment capture.");if(suspenseRepository.findByPaymentIdAndDeletedAtIsNull(id).isPresent())throw new IllegalStateException("This suspense payment has already been resolved.");StudentFinanceAccount account=requireActiveAccount(command.studentFinanceAccountId());Instant now=clock.instant();suspenseRepository.saveAndFlush(new StudentPaymentSuspenseResolution(payment,account,actor,now,command.reason()));issueReceipt(payment,account,actor,now);return paymentView(payment);}

    @Transactional public AllocationSummary allocate(UUID paymentId,AllocatePayment command,UUID actor){StudentAccountPayment payment=requirePayment(paymentId);requireVersion(payment.getVersion(),command.expectedPaymentVersion(),"Payment");FinanceInvoice invoice=invoiceRepository.findLockedByIdAndDeletedAtIsNull(command.invoiceId()).orElseThrow(()->new IllegalArgumentException("Invoice was not found."));StudentFinanceAccount effectiveAccount=effectiveAccount(payment);if(payment.getReconciliationStatus()!=StudentAccountPayment.ReconciliationStatus.RECONCILED||effectiveAccount==null)throw new IllegalStateException("Only a reconciled payment assigned to an account can be allocated.");if(!effectiveAccount.getId().equals(invoice.getStudentFinanceAccount().getId()))throw new IllegalArgumentException("Payment and invoice must belong to the same student finance account.");if(!payment.getTransactionCurrencyCode().equals(invoice.getTransactionCurrencyCode()))throw new IllegalArgumentException("Payment and invoice transaction currencies must match.");if(paymentReversalRepository.findByPaymentIdAndDeletedAtIsNull(paymentId).isPresent())throw new IllegalStateException("A reversed payment cannot be allocated.");List<StudentPaymentAllocation> active=activeAllocations();BigDecimal paymentAllocated=sum(active.stream().filter(item->item.getPayment().getId().equals(paymentId)).map(StudentPaymentAllocation::getTransactionAmount).toList());BigDecimal paymentBaseAllocated=sum(active.stream().filter(item->item.getPayment().getId().equals(paymentId)).map(StudentPaymentAllocation::getPaymentBaseAmount).toList());BigDecimal invoiceAllocated=sum(active.stream().filter(item->item.getInvoice().getId().equals(invoice.getId())).map(StudentPaymentAllocation::getTransactionAmount).toList());BigDecimal invoiceBaseAllocated=sum(active.stream().filter(item->item.getInvoice().getId().equals(invoice.getId())).map(StudentPaymentAllocation::getInvoiceBaseAmount).toList());List<FinanceCreditNote> postedCredits=creditNoteRepository.findAllByDeletedAtIsNullOrderByPreparedAtDescCreditNoteNumberDesc().stream().filter(note->note.getInvoice().getId().equals(invoice.getId())&&note.getStatus()==FinanceCreditNote.Status.POSTED).toList();BigDecimal credited=sum(postedCredits.stream().map(FinanceCreditNote::getTransactionAmount).toList());BigDecimal creditedBase=sum(postedCredits.stream().map(FinanceCreditNote::getBaseAmount).toList());BigDecimal paymentRemaining=payment.getTransactionAmount().subtract(paymentAllocated);BigDecimal invoiceRemaining=invoice.getGrossTransactionAmount().subtract(invoiceAllocated).subtract(credited);BigDecimal amount=command.transactionAmount();if(amount.compareTo(paymentRemaining)>0||amount.compareTo(invoiceRemaining)>0)throw new IllegalArgumentException("Allocation exceeds the available matching payment or invoice balance.");BigDecimal paymentBaseRemaining=payment.getBaseAmount().subtract(paymentBaseAllocated);BigDecimal invoiceBaseRemaining=invoice.getGrossBaseAmount().subtract(invoiceBaseAllocated).subtract(creditedBase);BigDecimal paymentBasis=proportionalBase(amount,payment.getTransactionAmount(),payment.getBaseAmount(),paymentRemaining,paymentBaseRemaining);BigDecimal invoiceBasis=proportionalBase(amount,invoice.getGrossTransactionAmount(),invoice.getGrossBaseAmount(),invoiceRemaining,invoiceBaseRemaining);StudentPaymentAllocation allocation=new StudentPaymentAllocation(referenceGenerator.nextAllocationNumber(),payment,invoice,amount,paymentBasis,invoiceBasis,actor,clock.instant(),command.reason());return allocationView(allocationRepository.saveAndFlush(allocation));}
    @Transactional public AllocationSummary reverseAllocation(UUID id,ControlledDecision command,UUID actor){StudentPaymentAllocation allocation=allocationRepository.findLockedById(id).orElseThrow(()->new IllegalArgumentException("Payment allocation was not found."));requireVersion(allocation.getVersion(),command.expectedVersion(),"Payment allocation");if(allocationReversalRepository.findByAllocationIdAndDeletedAtIsNull(id).isPresent())throw new IllegalStateException("Payment allocation is already reversed.");if(allocation.getAllocatedByUserId().equals(actor))throw new IllegalStateException("Allocation reversal requires a different Finance operator.");allocationReversalRepository.saveAndFlush(new StudentPaymentAllocationReversal(referenceGenerator.nextReversalNumber(),allocation,actor,clock.instant(),command.reason()));return allocationView(allocation);}
    @Transactional public PaymentSummary reversePayment(UUID id,ControlledDecision command,UUID actor){StudentAccountPayment payment=requirePayment(id);requireVersion(payment.getVersion(),command.expectedVersion(),"Payment");if(paymentReversalRepository.findByPaymentIdAndDeletedAtIsNull(id).isPresent())throw new IllegalStateException("Payment is already reversed.");if(activeAllocations().stream().anyMatch(allocation->allocation.getPayment().getId().equals(id)))throw new IllegalStateException("Reverse every active allocation before reversing the payment.");paymentReversalRepository.saveAndFlush(new StudentPaymentReversal(referenceGenerator.nextReversalNumber(),payment,actor,clock.instant(),command.reason()));return paymentView(payment);}

    @Transactional public CreditNoteSummary createCreditNote(CreateCreditNote command,UUID actor){FinanceInvoice invoice=invoiceRepository.findLockedByIdAndDeletedAtIsNull(command.invoiceId()).orElseThrow(()->new IllegalArgumentException("Invoice was not found."));if(command.lines().stream().map(CreditNoteLineInput::invoiceLineId).distinct().count()!=command.lines().size())throw new IllegalArgumentException("An invoice line can appear only once in a credit note.");List<FinanceInvoiceLine> invoiceLines=command.lines().stream().map(line->invoiceLineRepository.findByIdAndDeletedAtIsNull(line.invoiceLineId()).orElseThrow(()->new IllegalArgumentException("Invoice line was not found."))).toList();if(invoiceLines.stream().anyMatch(line->!line.getInvoice().getId().equals(invoice.getId())))throw new IllegalArgumentException("Every credit-note line must reference the selected invoice.");BigDecimal transactionTotal=sum(command.lines().stream().map(CreditNoteLineInput::transactionAmount).toList());BigDecimal baseTotal=sum(command.lines().stream().map(CreditNoteLineInput::baseAmount).toList());FinanceCreditNote note=creditNoteRepository.saveAndFlush(new FinanceCreditNote(referenceGenerator.nextCreditNoteNumber(),invoice,transactionTotal,baseTotal,command.creditNoteDate(),actor,clock.instant(),command.preparationReason()));List<FinanceCreditNoteLine> lines=new ArrayList<>();for(int index=0;index<command.lines().size();index++){CreditNoteLineInput input=command.lines().get(index);lines.add(new FinanceCreditNoteLine(note,index+1,invoiceLines.get(index),input.transactionAmount(),input.baseAmount(),input.reason()));}creditNoteLineRepository.saveAllAndFlush(lines);return creditNoteView(note);}
    @Transactional public CreditNoteSummary postCreditNote(UUID id,ControlledDecision command,UUID actor){FinanceCreditNote note=creditNoteRepository.findLockedById(id).orElseThrow(()->new IllegalArgumentException("Credit note was not found."));invoiceRepository.findLockedByIdAndDeletedAtIsNull(note.getInvoice().getId()).orElseThrow(()->new IllegalArgumentException("Invoice was not found."));note.post(actor,clock.instant(),command.reason(),command.expectedVersion());return creditNoteView(creditNoteRepository.saveAndFlush(note));}

    private StudentAccountPayment requirePayment(UUID id){return paymentRepository.findLockedById(id).orElseThrow(()->new IllegalArgumentException("Student payment was not found."));}
    private StudentFinanceAccount requireActiveAccount(UUID id){StudentFinanceAccount account=accountRepository.findByIdAndDeletedAtIsNull(id).orElseThrow(()->new IllegalArgumentException("Student finance account was not found."));if(!"ACTIVE".equals(account.getStatus()))throw new IllegalStateException("Student finance account must be active.");return account;}
    private StudentFinanceAccount effectiveAccount(StudentAccountPayment payment){if(payment.getStudentFinanceAccount()!=null)return payment.getStudentFinanceAccount();return suspenseRepository.findByPaymentIdAndDeletedAtIsNull(payment.getId()).map(StudentPaymentSuspenseResolution::getStudentFinanceAccount).orElse(null);}
    private void issueReceipt(StudentAccountPayment payment,StudentFinanceAccount account,UUID actor,Instant at){if(receiptRepository.findByPaymentIdAndDeletedAtIsNull(payment.getId()).isEmpty())receiptRepository.saveAndFlush(new StudentPaymentReceipt(payment,referenceGenerator.nextStudentReceiptNumber(),account,actor,at));}
    private RatedAmount rate(BigDecimal amount,String currency,Instant effectiveAt){if("USD".equals(currency))return new RatedAmount(null,amount,StudentAccountPayment.RatingStatus.RATED);List<ExchangeRate> rates=exchangeRateRepository.findEffectiveRates(currency,effectiveAt);if(rates.size()>1)throw new IllegalStateException("Multiple approved exchange rates cover the payment timestamp.");if(rates.isEmpty())return new RatedAmount(null,null,StudentAccountPayment.RatingStatus.UNRATED);ExchangeRate rate=rates.getFirst();return new RatedAmount(rate,amount.multiply(rate.getRateToBase()).setScale(2,RoundingMode.HALF_UP),StudentAccountPayment.RatingStatus.RATED);}
    private List<StudentPaymentAllocation> activeAllocations(){Set<UUID> reversed=allocationReversalRepository.findAllByDeletedAtIsNullOrderByReversedAtDesc().stream().map(item->item.getAllocation().getId()).collect(java.util.stream.Collectors.toSet());return allocationRepository.findAllByDeletedAtIsNullOrderByAllocatedAtDescAllocationNumberDesc().stream().filter(item->!reversed.contains(item.getId())).toList();}
    private BigDecimal proportionalBase(BigDecimal amount,BigDecimal originalAmount,BigDecimal originalBase,BigDecimal remainingAmount,BigDecimal remainingBase){if(amount.compareTo(remainingAmount)==0)return remainingBase;return amount.multiply(originalBase).divide(originalAmount,2,RoundingMode.HALF_UP);}
    private static BigDecimal sum(List<BigDecimal> values){return values.stream().reduce(BigDecimal.ZERO,BigDecimal::add);}
    private static String required(String value,String label){if(value==null||value.isBlank())throw new IllegalArgumentException(label+" is required.");return value.trim();}
    private static void requireVersion(long actual,long expected,String label){if(actual!=expected)throw new IllegalStateException(label+" changed since it was loaded. Refresh and try again.");}
    private List<StatementEntry> statementEntries(StudentFinanceAccount account){List<StatementEntry> entries=new ArrayList<>();invoiceRepository.findAllByDeletedAtIsNullOrderByPostedAtDescInvoiceNumberDesc().stream().filter(invoice->invoice.getStudentFinanceAccount().getId().equals(account.getId())).forEach(invoice->entries.add(new StatementEntry("INVOICE",invoice.getInvoiceNumber(),invoice.getPostedAt(),"Posted student invoice",invoice.getTransactionCurrencyCode(),invoice.getGrossTransactionAmount(),BigDecimal.ZERO,invoice.getGrossBaseAmount(),BigDecimal.ZERO)));creditNoteRepository.findAllByDeletedAtIsNullOrderByPreparedAtDescCreditNoteNumberDesc().stream().filter(note->note.getStatus()==FinanceCreditNote.Status.POSTED&&note.getInvoice().getStudentFinanceAccount().getId().equals(account.getId())).forEach(note->entries.add(new StatementEntry("CREDIT_NOTE",note.getCreditNoteNumber(),note.getPostedAt(),"Posted invoice correction",note.getTransactionCurrencyCode(),BigDecimal.ZERO,note.getTransactionAmount(),BigDecimal.ZERO,note.getBaseAmount())));paymentRepository.findAllByDeletedAtIsNullOrderByPaidAtDescPaymentNumberDesc().stream().filter(payment->payment.getReconciliationStatus()==StudentAccountPayment.ReconciliationStatus.RECONCILED&&Optional.ofNullable(effectiveAccount(payment)).map(StudentFinanceAccount::getId).filter(account.getId()::equals).isPresent()).forEach(payment->{entries.add(new StatementEntry("PAYMENT",payment.getPaymentNumber(),payment.getReconciledAt(),"Reconciled student payment",payment.getTransactionCurrencyCode(),BigDecimal.ZERO,payment.getTransactionAmount(),BigDecimal.ZERO,payment.getBaseAmount()));paymentReversalRepository.findByPaymentIdAndDeletedAtIsNull(payment.getId()).ifPresent(reversal->entries.add(new StatementEntry("PAYMENT_REVERSAL",reversal.getReversalNumber(),reversal.getReversedAt(),"Payment reversal",payment.getTransactionCurrencyCode(),payment.getTransactionAmount(),BigDecimal.ZERO,payment.getBaseAmount(),BigDecimal.ZERO)));});return entries;}
    private StudentAccountSummary accountView(StudentFinanceAccount account,BigDecimal balance){return new StudentAccountSummary(account.getId(),account.getAccountNumber(),account.getStudentId(),account.getStudentNumber(),account.getPrimaryEmail(),account.getStatus(),balance);}

    private ExchangeRateSummary rateView(ExchangeRate rate){return new ExchangeRateSummary(rate.getId(),rate.getSourceCurrencyCode(),rate.getBaseCurrencyCode(),rate.getRateToBase(),rate.getEffectiveFrom(),rate.getEffectiveTo(),rate.getSourceName(),rate.getSourceReference(),rate.getStatus(),rate.getPreparedByUserId(),rate.getApprovedByUserId(),rate.getApprovedAt(),rate.getRetiredByUserId(),rate.getRetiredAt(),rate.getVersion());}
    private PaymentSummary paymentView(StudentAccountPayment payment){StudentFinanceAccount account=effectiveAccount(payment);StudentPaymentReceipt receipt=receiptRepository.findByPaymentIdAndDeletedAtIsNull(payment.getId()).orElse(null);return new PaymentSummary(payment.getId(),payment.getPaymentNumber(),account==null?null:account.getId(),account==null?null:account.getAccountNumber(),payment.getPayerName(),payment.getProviderCode(),payment.getProviderTransactionReference(),payment.getPaymentChannel(),payment.getTransactionCurrencyCode(),payment.getTransactionAmount(),payment.getBaseCurrencyCode(),payment.getExchangeRate()==null?null:payment.getExchangeRate().getId(),payment.getBaseAmount(),payment.getRatingStatus(),payment.getPaidAt(),payment.getReconciliationStatus(),payment.getCapturedByUserId(),payment.getCapturedAt(),payment.getReconciledByUserId(),payment.getReconciledAt(),account==null,paymentReversalRepository.findByPaymentIdAndDeletedAtIsNull(payment.getId()).isPresent(),receipt==null?null:receipt.getReceiptNumber(),payment.getVersion());}
    private ReceiptSummary receiptView(StudentPaymentReceipt receipt){return new ReceiptSummary(receipt.getId(),receipt.getPayment().getId(),receipt.getPayment().getPaymentNumber(),receipt.getReceiptNumber(),receipt.getStudentFinanceAccount().getId(),receipt.getStudentFinanceAccount().getAccountNumber(),receipt.getIssuedAt());}
    private AllocationSummary allocationView(StudentPaymentAllocation allocation){StudentPaymentAllocationReversal reversal=allocationReversalRepository.findByAllocationIdAndDeletedAtIsNull(allocation.getId()).orElse(null);return new AllocationSummary(allocation.getId(),allocation.getAllocationNumber(),allocation.getPayment().getId(),allocation.getPayment().getPaymentNumber(),allocation.getInvoice().getId(),allocation.getInvoice().getInvoiceNumber(),allocation.getTransactionCurrencyCode(),allocation.getTransactionAmount(),allocation.getPaymentBaseAmount(),allocation.getInvoiceBaseAmount(),allocation.getRealisedExchangeDifference(),allocation.getAllocatedByUserId(),allocation.getAllocatedAt(),reversal!=null,reversal==null?null:reversal.getReversalNumber(),allocation.getVersion());}
    private CreditNoteSummary creditNoteView(FinanceCreditNote note){return new CreditNoteSummary(note.getId(),note.getCreditNoteNumber(),note.getInvoice().getId(),note.getInvoice().getInvoiceNumber(),note.getTransactionCurrencyCode(),note.getTransactionAmount(),note.getBaseCurrencyCode(),note.getBaseAmount(),note.getCreditNoteDate(),note.getStatus(),note.getPreparedByUserId(),note.getPreparedAt(),note.getPostedByUserId(),note.getPostedAt(),note.getVersion(),creditNoteLineRepository.findAllByCreditNoteIdAndDeletedAtIsNullOrderByLineNumberAsc(note.getId()).stream().map(line->new CreditNoteLineSummary(line.getId(),line.getLineNumber(),line.getInvoiceLine().getId(),line.getTransactionAmount(),line.getBaseAmount(),line.getReason())).toList());}
    private record RatedAmount(ExchangeRate rate,BigDecimal baseAmount,StudentAccountPayment.RatingStatus status) {}
    private record StatementEntry(String lineType,String reference,Instant occurredAt,String description,String transactionCurrencyCode,BigDecimal transactionDebit,BigDecimal transactionCredit,BigDecimal baseDebit,BigDecimal baseCredit){BigDecimal baseMovement(){return baseDebit.subtract(baseCredit);}}
}
